    correction: [{"quoi":"القاعدة","math":"نضع أصغر قوّة عاملا مشتركا، فيبقى داخل القوس عدد صغير"},{"quoi":"نُظهر العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">3<sup>111</sup> = 3<sup>109</sup> × 3<sup>2</sup></span>"},{"quoi":"نُخرج العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">3<sup>111</sup> - 3<sup>109</sup> = 3<sup>109</sup>(3<sup>2</sup> - 1)</span>"},{"quoi":"نحسب داخل القوس","math":"<span dir=\"ltr\" class=\"expr\">3<sup>2</sup> - 1 = 8</span>"},{"quoi":"نكتب الجداء","math":"<span dir=\"ltr\" class=\"expr\">3<sup>111</sup> - 3<sup>109</sup> = 8 × 3<sup>109</sup></span>"},{"quoi":"نُظهر القاسم 36","math":"<span dir=\"ltr\" class=\"expr\">8 × 3<sup>109</sup> = 36 × (2 × 3<sup>107</sup></span>"},{"quoi":"النتيجة","math":"العدد يساوي <span dir=\"ltr\" class=\"expr\">36 × 2 × 3<sup>107</sup></span> و منه يقبل القسمة على 36"}],
