    correction: [{"quoi":"القاعدة","math":"نضع أصغر قوّة عاملا مشتركا، فيبقى داخل القوس عدد صغير"},{"quoi":"نُظهر العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">5<sup>51</sup> = 5<sup>50</sup> × 5</span>"},{"quoi":"نُخرج العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">5<sup>50</sup> + 5<sup>51</sup> = 5<sup>50</sup>(1 + 5)</span>"},{"quoi":"نحسب داخل القوس","math":"<span dir=\"ltr\" class=\"expr\">1 + 5 = 6</span>"},{"quoi":"نكتب الجداء","math":"<span dir=\"ltr\" class=\"expr\">5<sup>50</sup> + 5<sup>51</sup> = 6 × 5<sup>50</sup></span>"},{"quoi":"نُظهر القاسم 75","math":"<span dir=\"ltr\" class=\"expr\">6 × 5<sup>50</sup> = 75 × (2 × 5<sup>48</sup></span>"},{"quoi":"النتيجة","math":"العدد يساوي <span dir=\"ltr\" class=\"expr\">75 × 2 × 5<sup>48</sup></span> و منه يقبل القسمة على 75"}],
