    correction: [{"quoi":"القاعدة","math":"نوحّد الأساس ثمّ نضع أصغر قوّة عاملا مشتركا"},{"quoi":"نوحّد الأساس في الحدّ الأوّل","math":"<span dir=\"ltr\" class=\"expr\">9<sup>254</sup> = 3<sup>508</sup></span>"},{"quoi":"نوحّد الأساس في الحدّ الثاني","math":"<span dir=\"ltr\" class=\"expr\">27<sup>169</sup> = 3<sup>507</sup></span>"},{"quoi":"نُخرج العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">3<sup>508</sup> + n × 3<sup>507</sup> = 3<sup>507</sup>(3 + n)</span>"},{"quoi":"نفكّك القاسم","math":"<span dir=\"ltr\" class=\"expr\">45 = 9 × 5</span>"},{"quoi":"العامل 9 موجود دائما","math":"<span dir=\"ltr\" class=\"expr\">3<sup>507</sup> = 3<sup>2</sup> × 3<sup>505</sup></span>"},{"quoi":"يبقى الشرط على 5","math":"بما أنّ 5 و 3 أوليان فيما بينهما، يجب أن يقبل <span dir=\"ltr\" class=\"expr\">3 + n</span> القسمة على 5"},{"quoi":"نحسب الحدّ الثابت","math":"<span dir=\"ltr\" class=\"expr\">3 = 3</span>"},{"quoi":"نبحث عن n","math":"نبحث عن n أصغر من 60 بحيث يقبل <span dir=\"ltr\" class=\"expr\">3 + n</span> القسمة على 5"},{"quoi":"النتيجة","math":"القيم الممكنة لـ n هي<span dir=\"ltr\" class=\"expr\">: 2 ؛ 7 ؛ 12 ؛ 17 ؛ 22 ؛ 27 ؛ 32 ؛ 37 ؛ 42 ؛ 47 ؛ 52 ؛ 57</span>"}],
