    correction: [{"quoi":"القاعدة","math":"نوحّد الأساس ثمّ نضع أصغر قوّة عاملا مشتركا"},{"quoi":"نُخرج العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">3<sup>1910</sup> + n × 3<sup>1908</sup> = 3<sup>1908</sup>(3<sup>2</sup> + n)</span>"},{"quoi":"نفكّك القاسم","math":"<span dir=\"ltr\" class=\"expr\">117 = 9 × 13</span>"},{"quoi":"العامل 9 موجود دائما","math":"<span dir=\"ltr\" class=\"expr\">3<sup>1908</sup> = 3<sup>2</sup> × 3<sup>1906</sup></span>"},{"quoi":"يبقى الشرط على 13","math":"بما أنّ 13 و 3 أوليان فيما بينهما، يجب أن يقبل <span dir=\"ltr\" class=\"expr\">3<sup>2</sup> + n</span> القسمة على 13"},{"quoi":"نحسب الحدّ الثابت","math":"<span dir=\"ltr\" class=\"expr\">3<sup>2</sup> = 9</span>"},{"quoi":"نبحث عن n","math":"نبحث عن n أصغر من 50 بحيث يقبل <span dir=\"ltr\" class=\"expr\">9 + n</span> القسمة على 13"},{"quoi":"النتيجة","math":"القيم الممكنة لـ n هي<span dir=\"ltr\" class=\"expr\">: 4 ؛ 17 ؛ 30 ؛ 43</span>"}],
